result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/clause_index.py", "content": """"Parse legal documents into a hierarchical clause index.

Top-level clauses (e.g. "3.") live in ``body``; numbered clauses after an
"EXHIBIT <letter>" line are indexed separately under that letter, with
numbering restarting at 1.
"""

import re

_CLAUSE_RE = re.compile(r"^(\d+(?:\.\d+)*)\.?\s+(.*)$")
_EXHIBIT_RE = re.compile(r"^EXHIBIT\s+([A-Z])\s*$", re.IGNORECASE)


def _split_heading(text):
    """Split 'Heading. Rest...' into ('Heading', 'Rest...')."""
    m = re.match(r"^(.*?)\.\s+(.*)$", text)
    if not m:
        return text.strip(), ""
    return m.group(1).strip(), m.group(2).strip()


def _parse_lines(lines):
    """Yield (number, heading, rest) for each clause-like line."""
    for line in lines:
        m = _CLAUSE_RE.match(line.strip())
        if not m:
            continue
        number, rest = m.group(1), m.group(2)
        heading, remainder = _split_heading(rest)
        if not heading:
            continue
        yield number, heading, remainder


def index_clauses(doc):
    body = []
    exhibits = {}
    current_exhibit = None
    last_top = None  # (container_list) where the last top-level clause went

    for number, heading, remainder in _parse_lines(doc.splitlines()):
        depth = number.count(".")
        node = {"number": number, "heading": heading, "children": []}
        if remainder:
            node["text"] = remainder

        if current_exhibit is None:
            if depth == 0:
                body.append(node)
                last_top = body
            else:
                if last_top is body and body:
                    parent = _find_parent(body, number)
                    if parent is not None:
                        parent["children"].append(node)
                    else:
                        body.append(node)
                else:
                    body.append(node)
        else:
            bucket = exhibits.setdefault(current_exhibit, [])
            if depth == 0:
                bucket.append(node)
                last_top = bucket
            elif last_top is bucket and bucket:
                parent = _find_parent(bucket, number)
                if parent is not None:
                    parent["children"].append(node)
                else:
                    bucket.append(node)
            else:
                bucket.append(node)

    return {"body": body, "exhibits": exhibits}


def _find_parent(container, number):
    """Find the nearest ancestor clause for a sub-number like '3.1' or '3.1.2'."""
    parts = number.rsplit(".", 1)[0]
    prefix = parts + "."
    for candidate in reversed(container):
        if number.startswith(candidate["number"] + "."):
            # walk down existing children to the closest ancestor
            node = candidate
            while True:
                deeper = [
                    c
                    for c in node["children"]
                    if (c["number"] + ".").startswith(prefix[: len(c["number"]) + 1])
                ]
                if not deeper:
                    return node
                node = deeper[-1]
    return None
